-- Descrizioni multilingua per prodotto (IT/EN/DE/FR/PT).
-- Aggiunge la colonna description_i18n e la popola per ogni prodotto.
-- Il sito mostra la descrizione nella lingua scelta; IT resta il fallback.

alter table public.products add column if not exists description_i18n jsonb not null default '{}'::jsonb;

update public.products set description_i18n='{"it":"3-TRENBOMED 150 di Deus Medical contiene Trenbolone Hexahydrobenzylcarbonate / Enanthate / Acetate 50mg/ml. Appartiene alla classe degli steroidi androgeno-anabolizzanti, in soluzione oleosa per uso intramuscolare. Confezione: 10 fiale / 1 mL — soluzione sterile I.M. La qualità di ogni lotto è verificabile nella sezione Lab test / QC. Conservare al riparo da luce e calore, fuori dalla portata dei bambini. Prodotto fornito esclusivamente a scopo di ricerca e valutazione analitica, non presentato come trattamento medico.","en":"3-TRENBOMED 150 by Deus Medical contains Trenbolone Hexahydrobenzylcarbonate / Enanthate / Acetate 50mg/ml. It belongs to the class of androgenic-anabolic steroids, in an oily solution for intramuscular use. Packaging: 10 fiale / 1 mL — soluzione sterile I.M. The quality of each batch can be verified in the Lab test / QC section. Store away from light and heat, out of the reach of children. Product supplied for research and analytical evaluation purposes only, not presented as a medical treatment.","de":"3-TRENBOMED 150 von Deus Medical enthält Trenbolone Hexahydrobenzylcarbonate / Enanthate / Acetate 50mg/ml. Es gehört zur Klasse der androgen-anabolen Steroide, in öliger Lösung zur intramuskulären Anwendung. Verpackung: 10 fiale / 1 mL — soluzione sterile I.M. Die Qualität jeder Charge kann im Bereich Lab test / QC überprüft werden. Vor Licht und Hitze geschützt aufbewahren, außerhalb der Reichweite von Kindern. Produkt ausschließlich zu Forschungs- und Analysezwecken bereitgestellt, nicht als medizinische Behandlung dargestellt.","fr":"3-TRENBOMED 150 de Deus Medical contient Trenbolone Hexahydrobenzylcarbonate / Enanthate / Acetate 50mg/ml. Il appartient à la classe des stéroïdes androgéno-anabolisants, en solution huileuse pour usage intramusculaire. Conditionnement : 10 fiale / 1 mL — soluzione sterile I.M. La qualité de chaque lot peut être vérifiée dans la section Lab test / QC. Conserver à l''abri de la lumière et de la chaleur, hors de portée des enfants. Produit fourni exclusivement à des fins de recherche et d''évaluation analytique, non présenté comme un traitement médical.","pt":"3-TRENBOMED 150 da Deus Medical contém Trenbolone Hexahydrobenzylcarbonate / Enanthate / Acetate 50mg/ml. Pertence à classe dos esteroides androgênico-anabolizantes, em solução oleosa para uso intramuscular. Embalagem: 10 fiale / 1 mL — soluzione sterile I.M. A qualidade de cada lote pode ser verificada na seção Lab test / QC. Conservar ao abrigo da luz e do calor, fora do alcance das crianças. Produto fornecido exclusivamente para fins de pesquisa e avaliação analítica, não apresentado como tratamento médico."}'::jsonb, updated_at=now() where slug='3-trenbomed-150';
